import{_ as n,C as d,o as t,c as s,a3 as a,b as i,w as o,a as c,E as l,a4 as h}from"./chunks/framework.B02wg2PO.js";const y=JSON.parse('{"title":"Runs","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/runs.md","filePath":"concepts/runs.md"}'),u={name:"concepts/runs.md"};function p(g,e,m,f,v,b){const r=d("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h1><p>A <strong>Run</strong> is the durable, shared-context unit of delegated work. It is what makes Saidi different from a long chat session.</p><p>Unlike a one-off delegation, a Run:</p><ul><li>has its <strong>own thread</strong> you can open and keep chatting into, separate from the main chat;</li><li>is orchestrated by <strong>PRIME</strong>, which delegates to project and department agents, relays their questions, and answers you — you only ever talk to PRIME;</li><li>keeps <strong>one shared context</strong> across every agent that participates: each agent resumes its own provider session and, for coding, accumulates on <strong>one</strong> branch, so context is never lost and a fresh branch is not cut every time.</li></ul><p>Runs are persisted (Mongo, mirrored under <code>memory/runs/&lt;id&gt;/</code>) and survive a server restart.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p><code>RunStatus</code> is defined at <code>src/orchestrator/runs/types.ts:18</code>.</p>',7)),(t(),i(h,null,{default:o(()=>[l(r,{id:"mermaid-35",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20direction%20LR%0A%20%20%20%20%5B*%5D%20--%3E%20active%3A%20created%0A%20%20%20%20active%20--%3E%20awaiting_input%3A%20blocked%0A%20%20%20%20awaiting_input%20--%3E%20active%3A%20answered%0A%20%20%20%20active%20--%3E%20paused%3A%20stop%0A%20%20%20%20paused%20--%3E%20active%3A%20resume%0A%20%20%20%20active%20--%3E%20error%3A%20turn%20failed%0A%20%20%20%20error%20--%3E%20active%3A%20reopen%0A%20%20%20%20active%20--%3E%20done%3A%20objective%20met%0A%20%20%20%20active%20--%3E%20cancelled%3A%20cancel%0A%20%20%20%20done%20--%3E%20%5B*%5D%0A%20%20%20%20cancelled%20--%3E%20%5B*%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>active</code></td><td>PRIME or a delegated agent is working</td></tr><tr><td><code>awaiting_input</code></td><td>Blocked on a question or an approval gate</td></tr><tr><td><code>paused</code></td><td>Stopped but resumable</td></tr><tr><td><code>done</code></td><td>PRIME reported the objective met</td></tr><tr><td><code>error</code></td><td>A turn failed</td></tr><tr><td><code>cancelled</code></td><td>You stopped it</td></tr></tbody></table><p>Transitions that deserve your attention are stamped as a <code>RunAttention</code> record, whose id changes only on entering a new attention-worthy state — so a reconnecting client can de-duplicate the notice without losing it.</p><h2 id="participants" tabindex="-1">Participants <a class="header-anchor" href="#participants" aria-label="Permalink to &quot;Participants&quot;">​</a></h2><p>Every agent that has taken part is a <code>RunParticipant</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td><code>key</code></td><td>Registry name, or <code>PRIME</code></td></tr><tr><td><code>kind</code></td><td><code>prime</code> | <code>project</code> | <code>custom</code></td></tr><tr><td><code>branch</code></td><td>The one branch this participant accumulates commits on</td></tr><tr><td><code>workDir</code></td><td>Per-run workspace (custom agents get their own, so concurrent runs never share a dir)</td></tr><tr><td><code>providerSessionId</code></td><td>The resumable session — plus the cwd, mode, and sandbox it was created with, since a mismatch must not resume</td></tr><tr><td><code>memoryStale</code></td><td>Set when the session was compacted since memory was last injected; the next delegation re-sends the memory block</td></tr><tr><td><code>contextTokens</code> / <code>usage</code></td><td>Context occupancy and cumulative cost for this participant</td></tr></tbody></table><h2 id="execution-modes" tabindex="-1">Execution modes <a class="header-anchor" href="#execution-modes" aria-label="Permalink to &quot;Execution modes&quot;">​</a></h2><p><strong><code>guided</code></strong> — the <em>engine</em> owns the dispatch loop. It selects ready tasks from the frozen plan, batches independent ones, verifies each result, and advances. PRIME plans once, answers escalations, and summarises. This removes the two failure modes of the alternative: the model moving its own goalposts, and looping.</p><p><strong><code>autonomous</code></strong> — PRIME decides what happens next on every step. Flexible enough to re-plan when the brief turns out to be wrong; use it for genuinely exploratory work.</p><h2 id="in-flight-work-and-crash-recovery" tabindex="-1">In-flight work and crash recovery <a class="header-anchor" href="#in-flight-work-and-crash-recovery" aria-label="Permalink to &quot;In-flight work and crash recovery&quot;">​</a></h2><p>Each executing delegation is written to <code>inFlights</code> as a <code>RunInFlight</code> — its kind (<code>work</code>, <code>ask</code>, <code>agent</code>, <code>approval</code>, <code>verify</code>), target, task, and start time — and cleared when it settles. A crash or restart can then tell you <em>exactly what was killed mid-flight</em>, not just that the run was interrupted. Work you had already approved is marked so PRIME can re-delegate with <code>approved: true</code> instead of re-asking.</p><h2 id="accounting" tabindex="-1">Accounting <a class="header-anchor" href="#accounting" aria-label="Permalink to &quot;Accounting&quot;">​</a></h2><ul><li><strong><code>usageLog</code></strong> — one <code>RunUsageEntry</code> per settled LLM call: actor, models (the one it actually ran on first), token counts, cost, duration, and the report length before clipping. Calls whose provider reported no price are flagged <code>unpriced</code> rather than silently rendered as free.</li><li><strong><code>verificationLog</code></strong> — every gate verdict, in order, append-only, at run level so it survives plan amendments that drop the task it was about.</li><li><strong><code>optimizationReport</code></strong> — first-pass task count, retries, failure kinds, total cost, max context.</li></ul><h2 id="sharing" tabindex="-1">Sharing <a class="header-anchor" href="#sharing" aria-label="Permalink to &quot;Sharing&quot;">​</a></h2><p>A Run has a <code>createdBy</code> (budgets, permissions, and connections resolve against that member) and an optional <code>sharedWith</code> list. Viewers can watch the thread but not steer it — steering stays with the owner plus admins holding <code>runs.steerAll</code>.</p><p>See also: <a href="./plans-and-tasks">Plans &amp; Tasks</a> · <a href="/docs/reference/run-object">The Run Object</a></p>',15))])}const k=n(u,[["render",p]]);export{y as __pageData,k as default};
